mapper.select:
select s.*, u.phone, u.real_name, u.avatar
from store_staff s
left join user u on s.user_id = u.id


        and s.id = #{id}


        and s.store_id = #{storeId}


        and s.user_id = #{userId}


        and s.status = #{status}


        and u.phone like CONCAT('%', #{phone}, '%')


        and u.real_name like CONCAT('%', #{realName}, '%')


        and (u.phone like CONCAT('%', #{keyword}, '%') or u.real_name like CONCAT('%', #{keyword}, '%'))


        and s.remark like CONCAT('%', #{remark}, '%')



            and s.deleted = #{deleted}


            and s.deleted = 0



order by s.created_time desc, s.id desc

mapper.update:
update store_staff
status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}, deleted = #{deleted},
where id = #{id}
